<?php require __DIR__.'/_start.php';$labels=['open'=>'Yeni','in_progress'=>'İnceleniyor','resolved'=>'Çözüldü']; ?>
<section class="admin-card"><form class="d-flex flex-wrap gap-3" method="get"><label for="ticket-status">Talep durumu</label><select id="ticket-status" class="form-select w-auto" name="status"><option value="">Tümü</option><?php foreach($labels as$key=>$label): ?><option value="<?= e($key) ?>" <?= $filter===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select><button class="btn btn-outline-dark">Filtrele</button></form><p class="muted mt-3"><?= $total ?> talep · Bu ekran e-posta göndermez.</p><?php if(!$tickets): ?><p class="empty-state">Bu görünümde destek talebi bulunmuyor.</p><?php endif ?><?php foreach($tickets as$t): ?><article class="customer-card mb-3"><div class="d-flex flex-wrap justify-content-between gap-2"><h2 class="h5 text-break"><?= e($t['subject']) ?></h2><span class="status-pill"><?= e($labels[$t['status']]) ?></span></div><p class="text-break"><?= e($t['name']) ?> · <a href="mailto:<?= e($t['email']) ?>"><?= e($t['email']) ?></a></p><p class="text-break"><?= nl2br(e($t['message'])) ?></p><small><?= e($t['created_at']) ?> · Referans <?= e($t['reference']) ?></small><form class="d-flex flex-wrap gap-2 mt-3" method="post" action="<?= e(url('admin/support/status')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label for="ticket-<?= (int)$t['id'] ?>">Yeni durum</label><select class="form-select w-auto" name="status" id="ticket-<?= (int)$t['id'] ?>"><?php foreach($labels as$key=>$label): ?><option value="<?= e($key) ?>" <?= $t['status']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select><button class="btn btn-outline-dark">Durumu kaydet</button></form></article><?php endforeach ?><?php if($number>1): ?><a href="<?= e(url('admin/support?'.http_build_query(['status'=>$filter,'p'=>$number-1]))) ?>">← Önceki</a><?php endif ?><?php if($number*25<$total): ?><a class="ms-3" href="<?= e(url('admin/support?'.http_build_query(['status'=>$filter,'p'=>$number+1]))) ?>">Sonraki →</a><?php endif ?></section>
<?php require __DIR__.'/_end.php'; ?>
